function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('.elementor-price-list-item').each((_, el) => {
    const $item = $(el);

    // Name
    const $title = $item.find('.elementor-price-list-title');
    const nameRaw = $title.text();
    const name = cleanText(nameRaw);
    if (!name) return;

    // Price
    const $priceSpan = $item.find('.elementor-price-list-price');
    let price = null;
    if ($priceSpan.length) {
      price = parsePrice(cleanText($priceSpan.text()));
    }

    // Description
    const $desc = $item.find('.elementor-price-list-description');
    const description = $desc.length ? cleanText($desc.text()) : null;

    // Section (nearest heading within the same section)
    const $section = $item.closest('.elementor-section');
    let section = null;
    if ($section.length) {
      const $heading = $section.find('.elementor-heading-title').first();
      if ($heading.length) {
        section = cleanText($heading.text());
      }
    }

    // Dedup
    const key = `${section ?? ''}|${name}|${description ?? ''}|${price ?? ''}`;
    if (!seen.has(key)) {
      seen.add(key);
      items.push({ section, name, description, price });
    }
  });

  return items;
}
```

